export const INSURANCE_WORKFLOWS: readonly InsuranceWorkflowDefinition[] = [
  { id:'new-claim', name:'Prepare an Insurance Claim', description:'Organize a new insurance claim and prepare a factual submission package with a source-linked timeline and document checklist.', family:'New Claims', risk:'MEDIUM', requiresReview:true, primaryKeyword:'insurance claims', monthlySearches:12100, cpc:49.83, competition:'LOW', supportingKeywords:['file a claim','state farm file a claim','insurance claim'], intake:['insurer','policy number','claim number','loss date','loss type','loss location','parties','estimated loss'], requiredEvidence:['policy/coverage documents','photos or records','estimates/invoices','prior correspondence'], outputs:['claim fact sheet','source-linked timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What documents do I need to file an insurance claim?',a:'You need your policy or declarations page, photos or records of the damage, repair estimates or invoices, and any prior correspondence with your insurer. The specific documents depend on the type of claim.'},{q:'How long do I have to file a claim after a loss?',a:'Time limits vary by policy type, insurer, and state. Check your policy for the reporting deadline and any proof-of-loss requirements. Do not delay — late filing can reduce or eliminate coverage.'},{q:'What happens after I submit my claim?',a:'The insurer assigns an adjuster, reviews the documentation, and issues a decision. They may request additional information, schedule an inspection, or make an initial offer. Keep records of every interaction.'}] },
  { id:'homeowners-claim', name:'Prepare a Homeowners Insurance Claim', description:'Organize a homeowners insurance claim with damage photos, repair estimates, policy coverage, and a documented loss inventory.', family:'New Claims', risk:'MEDIUM', requiresReview:true, primaryKeyword:'home insurance claim', monthlySearches:1000, cpc:18.41, competition:'MEDIUM', supportingKeywords:['homeowners insurance claim','how to file a claim with homeowners insurance','home insurance file a claim'], intake:['insurer','policy number','property address','loss date','loss type','estimated damage','occupancy status'], requiredEvidence:['policy/declarations page','photos of damage','repair estimates','receipts for emergency repairs','prior correspondence'], outputs:['loss inventory','damage timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'How do I file a homeowners insurance claim?',a:'Contact your insurer, document the damage with photos and receipts, get repair estimates, and submit a proof-of-loss form. Keep copies of everything and note the claim number.'},{q:'What is covered under a standard homeowners policy?',a:'Coverage depends on your policy form (HO-3, HO-5, etc.). Most cover sudden and accidental damage but exclude floods, earthquakes, and wear-and-tear. Check your declarations page for specifics.'},{q:'Should I get my own repair estimate?',a:'Yes. An independent estimate gives you a comparison point against the insurer\'s adjuster. It helps identify underpayment and documents the actual cost of repairs.'}] },
  { id:'auto-claim', name:'Prepare an Auto Insurance Claim', description:'Organize an auto accident, collision, comprehensive, or property-damage claim with photos, police reports, and repair estimates.', family:'New Claims', risk:'HIGH', requiresReview:true, primaryKeyword:'car insurance claim', monthlySearches:5400, cpc:23.67, competition:'LOW', supportingKeywords:['auto insurance claim','car accident claim','accident claim','auto adjuster'], intake:['accident date','vehicles','drivers','insurer','claim number','damage description','liability position'], requiredEvidence:['photos','police report','repair estimate','vehicle records','witness information','insurer correspondence'], outputs:['accident timeline','damage/evidence matrix','claim response','supplement letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What information do I need to file an auto insurance claim?',a:'You need the accident date and location, vehicle and driver information, photos of damage, a police report if available, repair estimates, and your insurance policy and claim number.'},{q:'How long does an auto insurance claim take?',a:'Simple claims resolve in days; complex liability disputes can take weeks or months. The insurer must acknowledge your claim within a set timeframe — check your state\'s regulations.'},{q:'What if the other driver was at fault?',a:'Document the accident thoroughly. You can file through your own collision coverage or the at-fault driver\'s liability coverage. Your insurer may subrogate to recover the payout.'}] },
  { id:'commercial-property-claim', name:'Prepare a Commercial Property Claim', description:'Organize business property loss, supporting records, and an insurer response or supplemental claim for a commercial property.', family:'New Claims', risk:'CRITICAL', requiresReview:true, primaryKeyword:'business property damage insurance', monthlySearches:1000, cpc:1.77, competition:'HIGH', supportingKeywords:['commercial property damage claim','commercial property damage','commercial insurance claims'], intake:['business','policy','claim number','loss date','property affected','business interruption context'], requiredEvidence:['policy','photos','repair estimates','invoices','asset records','business records','insurer correspondence'], outputs:['commercial loss inventory','timeline','valuation/evidence matrix','review-ready claim response'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is a commercial property insurance claim?',a:'It is a claim filed under a business property policy for physical damage to commercial buildings, equipment, inventory, or other insured assets caused by a covered peril.'},{q:'Does commercial property insurance cover business interruption?',a:'Business interruption coverage is a separate endorsement or policy section. Check whether your policy includes it and what triggers coverage — typically physical damage that forces closure.'},{q:'What records does a commercial claim require?',a:'You need the policy, photos of damage, repair estimates, asset and inventory records, financial statements for interruption losses, and all insurer correspondence.'}] },
  { id:'renters-insurance-claim', name:'Prepare a Renters Insurance Claim', description:'Organize a renters insurance claim for personal property loss, theft, or damage with a documented inventory and policy review.', family:'New Claims', risk:'MEDIUM', requiresReview:true, primaryKeyword:'renters insurance claim', monthlySearches:480, cpc:12.77, competition:'LOW', supportingKeywords:['renters insurance file a claim','how to file a renters insurance claim','renters insurance claim denied'], intake:['insurer','policy number','rental address','loss date','loss type','itemized loss'], requiredEvidence:['policy/declarations page','photos of damage/loss','receipts or proof of ownership','police report if theft','landlord correspondence'], outputs:['personal property inventory','loss timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What does renters insurance cover?',a:'Renters insurance typically covers personal property loss from theft, fire, smoke, water damage (not flooding), and certain other perils. It may also include liability and additional living expenses.'},{q:'How do I document my loss for a renters claim?',a:'Create an itemized inventory with photos, receipts, serial numbers, and estimated replacement cost. Include a police report for theft claims and any landlord notices.'},{q:'Is there a payout limit on renters insurance?',a:'Yes. Policies have coverage limits per category (e.g., electronics, jewelry) and a total personal property limit. Check your declarations page for sub-limits and deductible.'}] },
  { id:'denied-claim', name:'Respond to a Denied Insurance Claim', description:'Analyze a denial and build a source-supported response or appeal with the denial reason, policy provision, evidence, and requested outcome.', family:'Denied Claims', risk:'HIGH', requiresReview:true, primaryKeyword:'insurance claim denied', monthlySearches:1300, cpc:47.03, competition:'LOW', supportingKeywords:['denied claim','claim was denied','appealing insurance denial','insurance company denied claim'], intake:['denial letter','claim number','denial date','stated reason','policy provision cited','appeal instructions','deadline'], requiredEvidence:['denial letter','policy excerpts','claim records','supporting photos/reports','prior correspondence'], outputs:['denial X-Ray','issue list','evidence gaps','response/appeal draft','mail-ready packet'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What should I do if my insurance claim is denied?',a:'Read the denial letter carefully, identify the stated reason and cited policy provision, gather supporting evidence, and prepare a written response or appeal before the deadline. Do not accept a verbal denial — request it in writing.'},{q:'How long do I have to appeal a denied insurance claim?',a:'Appeal deadlines vary by policy type, insurer, and state. Check your policy and the denial letter for the specific deadline. Some policies allow 60 days; others may be shorter.'},{q:'Can I appeal a claim denial without a lawyer?',a:'Yes. Many appeals are filed by policyholders directly. The key is identifying the denial reason, citing the relevant policy language, and providing evidence that contradicts the insurer\'s position.'}] },
  { id:'denied-home-claim', name:'Respond to a Denied Home Insurance Claim', description:'Analyze a denied homeowners claim and prepare a documented response with damage evidence, estimates, and policy coverage arguments.', family:'Denied Claims', risk:'HIGH', requiresReview:true, primaryKeyword:'home insurance claim denied', monthlySearches:110, cpc:18.41, competition:'LOW', supportingKeywords:['homeowners insurance claim denied','home insurance denied claim','house insurance claim denied'], intake:['denial letter','policy number','claim number','denial reason','coverage section cited','deadline'], requiredEvidence:['denial letter','policy/declarations page','photos of damage','repair estimates','inspector reports','prior correspondence'], outputs:['denial analysis','coverage argument','evidence matrix','appeal draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Why would a home insurance claim be denied?',a:'Common reasons include excluded peril, insufficient documentation, late filing, misrepresentation, or the insurer\'s determination that damage is from wear and tear rather than a covered event.'},{q:'How do I appeal a denied homeowners claim?',a:'Review the denial letter and cited policy exclusion, gather repair estimates and photos, document the covered peril, and file a written appeal citing the relevant policy language. Keep copies of everything.'},{q:'What if the insurer says the damage is pre-existing?',a:'Gather evidence showing the damage is new or from a specific event: dated photos, weather records, contractor assessments, and maintenance records showing the property was in good condition before the loss.'}] },
  { id:'auto-claim-denial', name:'Respond to a Denied Auto Insurance Claim', description:'Analyze an auto claim denial and prepare a factual response or appeal with accident facts, policy coverage, and evidence.', family:'Denied Claims', risk:'HIGH', requiresReview:true, primaryKeyword:'car insurance claim denied', monthlySearches:90, cpc:255.00, competition:'LOW', supportingKeywords:['auto insurance claim denied','denied car insurance claim','car insurance denied claim what to do','car insurance refusing to pay claim'], intake:['denial letter','claim facts','liability/coverage reason','deadline','requested outcome'], requiredEvidence:['denial letter','policy','accident report','photos','repair estimates','prior communications'], outputs:['denial analysis','fact/evidence matrix','appeal response'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What if my auto insurer denies my claim?',a:'Read the denial letter, identify the reason (coverage exclusion, liability dispute, late reporting), gather evidence, and file a written appeal. If the denial involves another driver, your insurer may subrogate.'},{q:'Can my car insurance company refuse to pay?',a:'They can deny coverage for specific reasons — excluded driver, uncovered peril, policy lapse, or liability disputes. They must provide a written denial with the reason and cited policy provision.'},{q:'What if the other driver\'s insurance denies my claim?',a:'You can file through your own collision coverage, file a complaint with your state insurance commissioner, or pursue the at-fault driver directly. Document all communications.'}] },
  { id:'life-insurance-denial', name:'Respond to a Denied Life Insurance Claim', description:'Organize a life insurance denial and prepare a source-supported response with the policy, claim record, and denial explanation.', family:'Denied Claims', risk:'CRITICAL', requiresReview:true, primaryKeyword:'life insurance claim denied', monthlySearches:210, cpc:18.28, competition:'LOW', supportingKeywords:['life insurance denied','life insurance policy denial','life insurance payout denied','life insurance rejection reasons'], intake:['policy','claimant/beneficiary role','denial letter','policy provision cited','deadline'], requiredEvidence:['policy','death/claim records as applicable','denial letter','insurer communications','supporting records'], outputs:['denial analysis','source map','evidence checklist','review-ready response'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Why would a life insurance claim be denied?',a:'Common reasons include material misrepresentation during application, policy lapse for non-payment, death outside coverage period, or exclusion clauses (e.g., suicide within contestability period). The denial letter must state the reason.'},{q:'Can I appeal a life insurance claim denial?',a:'Yes. Request the denial in writing, review the cited policy provision, gather evidence contradicting the denial reason, and file a written appeal within the deadline. Consider requesting the insurer\'s claim file.'},{q:'What is the contestability period for life insurance?',a:'Typically two years from the policy issue date. During this period, the insurer can investigate and deny claims for material misstatements on the application. After contestability, denial grounds are narrower.'}] },
  { id:'health-medical-denial', name:'Respond to a Health or Medical Insurance Denial', description:'Organize a medical claim or coverage denial and prepare a documented appeal package with denial codes, medical records, and policy provisions.', family:'Health & Disability', risk:'CRITICAL', requiresReview:true, primaryKeyword:'medical insurance claim denial', monthlySearches:320, cpc:0.15, competition:'LOW', supportingKeywords:['health insurance denial','medical insurance denial','appealing medical insurance denials','health insurance appeal process'], intake:['member/claim number','service/date','denial reason','code/reason cited','appeal deadline'], requiredEvidence:['denial/EOB','policy or plan materials','provider records','bills','supporting documentation'], outputs:['denial X-Ray','evidence matrix','appeal checklist','review-ready appeal letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'How do I appeal a health insurance denial?',a:'Review the EOB or denial letter, identify the denial code and reason, gather medical records and provider letters, and file a formal appeal within the deadline. Many plans require exhausting internal appeals before external review.'},{q:'What is an EOB and why does it matter?',a:'An Explanation of Benefits (EOB) shows what the insurer paid and what they denied. It includes denial codes that tell you the reason — understanding these codes is the first step in building an appeal.'},{q:'What are common reasons for medical claim denials?',a:'Common reasons include not medically necessary, out-of-network, pre-authorization required, coding errors, coverage excluded, and timely filing limits. Each requires a different appeal approach.'}] },
  { id:'disability-claim-denial', name:'Respond to a Disability Insurance Denial', description:'Organize a short- or long-term disability denial and prepare a documented appeal with medical evidence, policy definitions, and provider statements.', family:'Health & Disability', risk:'CRITICAL', requiresReview:true, primaryKeyword:'disability insurance denied', monthlySearches:110, cpc:22.14, competition:'MEDIUM', supportingKeywords:['short term disability denied','long term disability denial','reasons short term disability can be denied','denied long term disability coverage'], intake:['claim type','policy/certificate','denial letter','claimed limitation as stated by user','deadline','appeal instructions'], requiredEvidence:['denial letter','policy/certificate','user-provided records','insurer correspondence'], outputs:['denial analysis','document checklist','appeal draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Why was my disability claim denied?',a:'Common reasons include insufficient medical evidence, failure to meet the policy\'s definition of disability, missed deadlines, pre-existing condition exclusions, or the insurer\'s determination that you can work in some occupation.'},{q:'What is the difference between short-term and long-term disability appeals?',a:'Short-term disability (STD) appeals often involve employer plan rules and shorter deadlines. Long-term disability (LTD) appeals may involve ERISA requirements and can be more complex. Both require a written appeal within the deadline.'},{q:'What medical evidence do I need for a disability appeal?',a:'Gather treating physician statements, functional capacity evaluations, diagnostic test results, medication records, and vocational assessments. The key is showing you cannot perform the duties of your occupation as defined by the policy.'}] },
  { id:'workers-comp-denial', name:'Respond to a Workers Compensation Denial', description:'Organize a denied workers compensation claim with incident records, medical evidence, employment documentation, and a structured appeal.', family:'Denied Claims', risk:'CRITICAL', requiresReview:true, primaryKeyword:'workers comp denied claim', monthlySearches:210, cpc:15.50, competition:'LOW', supportingKeywords:['workers compensation denied','denied workers comp claim','workers comp claim denied what to do','workers comp denied'], intake:['employer','claim number','injury date','denial reason','denial letter','state of employment'], requiredEvidence:['denial letter','incident report','medical records','wage records','witness statements','employer correspondence'], outputs:['denial analysis','evidence matrix','appeal checklist','review-ready response'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What should I do if my workers comp claim is denied?',a:'Read the denial letter, note the reason and deadline, gather medical records and incident reports, and file a formal appeal with your state\'s workers compensation board. Deadlines are often strict — act quickly.'},{q:'Can I appeal a workers comp denial without a lawyer?',a:'Yes, though it can be complex. You need to file the appropriate forms with your state board, present medical evidence, and attend a hearing. Many states offer guides for self-represented claimants.'},{q:'What are common reasons workers comp claims are denied?',a:'Common reasons include late reporting, no medical evidence, injury not work-related, pre-existing condition, or the employer disputes the claim. The denial letter must state the specific reason.'}] },
  { id:'medical-necessity-appeal', name:'Medical Necessity Appeal', description:'Build a medical-necessity appeal with provider letters, clinical evidence, treatment records, and policy language for a denied medical service.', family:'Health & Disability', risk:'CRITICAL', requiresReview:true, primaryKeyword:'medical necessity denial appeal', monthlySearches:170, cpc:12.00, competition:'LOW', supportingKeywords:['medical necessity appeal','appeal medical necessity denial','medical necessity denial letter','medical necessity insurance denial'], intake:['denial letter','service/procedure denied','denial code','provider name','clinical rationale','appeal deadline'], requiredEvidence:['denial letter/EOB','provider letter of medical necessity','clinical guidelines','treatment records','peer-review references'], outputs:['necessity argument with citations','evidence checklist','review-ready appeal letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is a medical necessity denial?',a:'The insurer denies coverage for a service or treatment they deem not medically necessary, often despite a provider\'s recommendation. The denial typically cites specific clinical criteria or plan exclusions.'},{q:'How do I appeal a medical necessity denial?',a:'Obtain a detailed letter from your treating provider explaining why the service is medically necessary, reference clinical guidelines or peer-reviewed evidence, and file a formal appeal within the deadline. Include treatment records and diagnostic results.'},{q:'What if the insurer says the treatment is experimental?',a:'Cite peer-reviewed studies, FDA approvals, clinical guidelines from recognized medical societies, and any plan language covering the treatment. Ask for the specific criteria the insurer used to make the determination.'}] },
  { id:'prior-auth-denial', name:'Prior Authorization Denial', description:'Respond to a denied prior authorization request with clinical evidence, plan criteria, and a provider-supported appeal.', family:'Health & Disability', risk:'HIGH', requiresReview:true, primaryKeyword:'prior authorization denied', monthlySearches:260, cpc:8.50, competition:'LOW', supportingKeywords:['prior auth denial','prior authorization appeal','insurance denied prior authorization','prior authorization denied what to do'], intake:['denial notice','service/procedure','plan criteria cited','provider name','clinical rationale','appeal deadline'], requiredEvidence:['denial notice','provider letter','clinical guidelines','medical records','plan documents'], outputs:['criteria analysis','evidence checklist','review-ready appeal'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What does prior authorization mean?',a:'Prior authorization is when your insurer must approve a service, medication, or procedure before you receive it. If denied, the insurer is saying the service does not meet their criteria for coverage.'},{q:'Can I appeal a prior authorization denial?',a:'Yes. Gather your provider\'s clinical rationale, reference the plan\'s coverage criteria, and file an appeal within the deadline. Ask for the specific criteria used to deny the request.'},{q:'How long does a prior auth appeal take?',a:'Urgent appeals are typically decided within 72 hours; standard appeals may take up to 30 days. Your plan documents should specify the timeline for your insurer.'}] },
  { id:'out-of-network-denial', name:'Out-of-Network Denial', description:'Respond to a denial based on out-of-network provider or service with plan documents, network status verification, and a documented appeal.', family:'Health & Disability', risk:'HIGH', requiresReview:true, primaryKeyword:'out of network denial', monthlySearches:140, cpc:9.20, competition:'LOW', supportingKeywords:['out of network insurance denial','out of network claim denied','out of network appeal','out of network coverage denial'], intake:['denial letter','provider name','service date','plan network status','emergency/no-network context','appeal deadline'], requiredEvidence:['denial letter','plan documents','provider network verification','medical records','emergency documentation if applicable'], outputs:['network status analysis','coverage argument','review-ready appeal'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Can I appeal if I went to an out-of-network provider?',a:'Yes, especially if there was no in-network option, it was an emergency, or you received a surprise bill. Many states have balance billing protections. Gather evidence of network inadequacy or emergency circumstances.'},{q:'What is a surprise medical bill?',a:'A surprise bill occurs when you receive care from an out-of-network provider at an in-network facility, often without your knowledge. Federal and many state laws provide protections and appeal pathways.'},{q:'What if there are no in-network specialists available?',a:'Document your attempts to find an in-network provider, including calls made and wait times. This "network inadequacy" argument can support an appeal for out-of-network coverage at in-network rates.'}] },
  { id:'water-damage-claim', name:'Water Damage Insurance Claim', description:'Prepare a water damage insurance claim with photos, source identification, mitigation records, and a documented loss inventory.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'water damage insurance claim', monthlySearches:1000, cpc:7.30, competition:'LOW', supportingKeywords:['water damage claim','water leak insurance claim','burst pipe insurance claim','homeowners insurance claim for water damage'], intake:['insurer','policy number','water source','discovery date','extent of damage','mitigation steps taken'], requiredEvidence:['photos of damage','water source identification','mitigation receipts','repair estimates','moisture/humidity readings','prior maintenance records'], outputs:['damage inventory','mitigation timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does homeowners insurance cover water damage?',a:'Most policies cover sudden and accidental water damage (burst pipes, accidental overflow) but exclude flooding, groundwater seepage, and gradual leaks. Check your policy for specifics and consider separate flood insurance.'},{q:'What should I do immediately after water damage?',a:'Stop the source if possible, document with photos and videos, contact your insurer, begin mitigation (remove standing water, dry the area), and keep all receipts. Do not discard damaged items before the insurer inspects.'},{q:'What is the difference between water damage and flood damage?',a:'Water damage typically comes from within the property (pipes, appliances). Flood damage comes from external rising water. Standard homeowners policies cover water damage but not floods — you need separate flood insurance.'}] },
  { id:'roof-damage-claim', name:'Roof Damage Insurance Claim', description:'Organize a roof damage claim with inspection photos, contractor estimates, storm records, and policy coverage documentation.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'roof insurance claim', monthlySearches:1900, cpc:28.64, competition:'LOW', supportingKeywords:['roof damage insurance claim','hail damage roof insurance claim','roof leak insurance claim','roof insurance claim denied'], intake:['insurer','policy number','roof type','damage type','discovery date','roof age','prior inspections'], requiredEvidence:['photos of roof damage','contractor inspection report','repair estimate','storm/weather records if applicable','prior roof maintenance records'], outputs:['damage assessment','timeline','valuation estimate','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does insurance cover roof damage?',a:'Most policies cover roof damage from sudden events like storms, hail, wind, and falling objects. They typically exclude wear and tear, age-related deterioration, and inadequate maintenance.'},{q:'How do I file a roof damage insurance claim?',a:'Document the damage with photos from multiple angles, get a contractor inspection and estimate, check your policy for coverage and deductible, and contact your insurer. Keep all records and do not make permanent repairs until the insurer inspects.'},{q:'What if my roof claim is denied?',a:'Common denial reasons include age/wear, excluded peril, or insufficient documentation. Get a second contractor opinion, document the specific covered event (storm records, hail reports), and file a written appeal.'}] },
  { id:'fire-smoke-claim', name:'Fire / Smoke Damage Claim', description:'Prepare a fire or smoke damage claim with damage photos, inventory, smoke residue documentation, and repair estimates.', family:'Property Damage', risk:'CRITICAL', requiresReview:true, primaryKeyword:'fire damage insurance claim', monthlySearches:210, cpc:15.54, competition:'LOW', supportingKeywords:['smoke damage insurance claims','fire damage claims','total loss fire claim','soot damage insurance claim'], intake:['insurer','policy number','fire date','cause if known','extent of damage','displacement status'], requiredEvidence:['fire department report','photos of damage','smoke/soot documentation','inventory of lost items','repair estimates','temporary housing receipts'], outputs:['loss inventory','damage timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does homeowners insurance cover fire damage?',a:'Yes, fire is a covered peril in virtually all standard homeowners policies. Coverage includes the dwelling, personal property, and additional living expenses if you are displaced.'},{q:'What should I document after a fire?',a:'Take extensive photos of all damage, create an inventory of lost or damaged items with estimated values, save the fire department report, and keep all receipts for temporary housing and expenses.'},{q:'What is smoke damage and is it covered?',a:'Smoke damage includes soot residue, odor, and staining from a fire. It is typically covered under the same fire coverage. Document with photos and professional cleaning assessments.'}] },
  { id:'property-damage-claim', name:'Property Damage Claim', description:'Organize a general property damage claim with photos, inspection reports, estimates, and a documented timeline of the loss event.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'property damage insurance claim', monthlySearches:260, cpc:0.00, competition:'LOW', supportingKeywords:['property damage insurance','damage claim','home damage','property damage adjuster'], intake:['insurer','policy number','property type','damage type','loss date','estimated loss','cause of damage'], requiredEvidence:['photos','inspection reports','estimates','invoices','policy/claim correspondence'], outputs:['damage inventory','timeline','valuation comparison','response/supplement letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What counts as property damage for an insurance claim?',a:'Physical damage to your insured property from a covered peril — storms, vandalism, fire, water damage, falling objects, and other events named in or not excluded by your policy.'},{q:'How is property damage valued?',a:'Insurers typically use actual cash value (ACV) or replacement cost value (RCV). ACV deducts depreciation; RCV pays the cost to replace the item without depreciation. Check your policy for which applies.'},{q:'What if I disagree with the insurer\'s damage estimate?',a:'Get an independent contractor or public adjuster estimate, document the discrepancy, and request a re-inspection or file a supplement. Keep detailed records of all estimates and communications.'}] },
  { id:'hail-damage-claim', name:'Hail Damage Insurance Claim', description:'Organize a hail damage claim with storm documentation, inspection photos, contractor assessments, and a detailed damage inventory.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'hail damage insurance claim', monthlySearches:480, cpc:32.87, competition:'LOW', supportingKeywords:['hail damage claim','hail damage roof insurance claim','hail damage insurance','file hail damage claim'], intake:['insurer','policy number','hail event date','affected property','roof type','vehicle damage if any'], requiredEvidence:['photos of hail damage','storm/hail reports from NWS','contractor inspection report','repair estimates','prior condition photos'], outputs:['damage assessment','storm timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does insurance cover hail damage?',a:'Yes, hail is typically a covered peril under comprehensive auto coverage and most homeowners policies. Document the event with dated photos and weather reports.'},{q:'How do I prove hail damage to my roof?',a:'Get a contractor inspection that identifies hail impact marks (dents, granule loss, bruising), cross-reference with local weather service hail reports, and take close-up photos of the damage pattern.'},{q:'What if the insurer says the damage is cosmetic?',a:'Hail damage to roofing can compromise the shingle\'s protective layer even if it looks minor. Get a contractor to document functional damage, not just cosmetic issues, and reference manufacturer warranty impacts.'}] },
  { id:'theft-vandalism-claim', name:'Theft or Vandalism Claim', description:'Document theft or vandalism losses and build a factual insurance submission or dispute with police reports and proof of ownership.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'auto theft claim denied', monthlySearches:10, cpc:10.38, competition:'MEDIUM', supportingKeywords:['stolen car insurance claim denied','car vandalism claim denied','stolen car claim denied','vandalism insurance claim'], intake:['incident date','property stolen/damaged','police report','claim number','insurer position'], requiredEvidence:['police report','photos','ownership records','receipts','keys/access records','insurer correspondence'], outputs:['loss inventory','timeline','evidence checklist','claim/response letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does insurance cover theft and vandalism?',a:'Homeowners and renters insurance cover theft of personal property. Auto comprehensive coverage covers vehicle theft and vandalism. You need a police report and proof of ownership for stolen items.'},{q:'What if my theft claim is denied?',a:'Common reasons include no police report, insufficient proof of ownership, policy exclusions, or the insurer suspects fraud. Gather receipts, serial numbers, photos, and the police report to support your claim.'},{q:'What proof of ownership do I need?',a:'Receipts, credit card statements, photos of the items in your home, serial numbers, appraisals for valuable items, and warranty records. For high-value items, check if your policy requires a scheduled endorsement.'}] },
  { id:'mold-damage-claim', name:'Mold Damage Insurance Claim', description:'Organize a mold damage claim with source identification, inspection reports, remediation estimates, and policy coverage documentation.', family:'Property Damage', risk:'HIGH', requiresReview:true, primaryKeyword:'mold damage insurance claim', monthlySearches:170, cpc:14.20, competition:'MEDIUM', supportingKeywords:['mold damage claim','mold insurance claim','homeowners insurance mold damage','mold coverage insurance'], intake:['insurer','policy number','discovery date','mold location','water source','extent of damage'], requiredEvidence:['photos of mold','moisture/humidity readings','mold inspection report','remediation estimate','water source identification','prior maintenance records'], outputs:['damage assessment','remediation timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does homeowners insurance cover mold damage?',a:'Coverage depends on the cause. If the mold results from a covered peril (sudden water damage from a burst pipe), it may be covered. Gradual leaks, humidity, or maintenance issues are typically excluded. Check your policy for mold coverage limits.'},{q:'How do I document mold for an insurance claim?',a:'Take photos of all visible mold, get a professional mold inspection with moisture readings, identify the water source, obtain remediation estimates, and keep records of any water damage events that preceded the mold.'},{q:'What if my mold claim is denied?',a:'If the mold came from a covered water damage event, cite the policy language and the initial water claim. If denied as a maintenance issue, document that the underlying cause was a sudden, accidental event covered by the policy.'}] },
  { id:'flood-damage-claim', name:'Flood Damage Insurance Claim', description:'Prepare a flood damage claim with FEMA documentation, flood zone records, damage photos, and a detailed loss inventory for NFIP or private flood insurance.', family:'Property Damage', risk:'CRITICAL', requiresReview:true, primaryKeyword:'flood damage insurance claim', monthlySearches:320, cpc:6.50, competition:'LOW', supportingKeywords:['flood insurance claim','flood damage claim','how to file a flood insurance claim','flood claim denied'], intake:['insurer (NFIP or private)','policy number','flood event date','flood source','property type','extent of damage'], requiredEvidence:['photos of flood damage','flood elevation certificate','NFIP/private policy','repair estimates','itemized loss inventory','flood zone documentation'], outputs:['flood damage inventory','timeline','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'Does homeowners insurance cover flood damage?',a:'No. Standard homeowners policies exclude flood damage. You need separate flood insurance through the NFIP (National Flood Insurance Program) or a private insurer. If you have flood insurance, file through that policy.'},{q:'How do I file a flood insurance claim?',a:'Contact your insurer immediately, take photos before cleanup, itemize all damaged property, keep receipts for emergency repairs and temporary housing, and submit a proof-of-loss within 60 days (NFIP) or your policy deadline.'},{q:'What if my flood claim is denied?',a:'Common reasons include lack of flood insurance, damage below the deductible, late proof-of-loss filing, or the insurer says the water was groundwater not flooding. Check the flood zone designation and get a hydrologist report if needed.'}] },
  { id:'underpaid-claim', name:'Dispute an Underpaid Insurance Claim', description:'Compare an insurer payment or estimate against documented loss evidence and prepare a factual supplemental dispute.', family:'Disputes & Appeals', risk:'HIGH', requiresReview:true, primaryKeyword:'underpaid insurance claim', monthlySearches:30, cpc:0.00, competition:'LOW', supportingKeywords:['underpaid claim','insurance company underpaid claim','insurance underpayment'], intake:['claim number','insurer estimate','payment amount','loss estimate','line-item differences','policy references'], requiredEvidence:['insurer estimate','contractor/appraiser estimate','receipts','photos','repair invoices','policy excerpts'], outputs:['valuation comparison','unexplained differences','missing support list','supplement/reconsideration letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What does it mean when a claim is underpaid?',a:'The insurer paid less than the actual cost of repair or replacement. This can happen due to adjuster error, lower estimates, depreciation deductions, or missing line items.'},{q:'How do I dispute an underpaid insurance claim?',a:'Compare the insurer\'s estimate line-by-line against your contractor estimate, document each discrepancy, provide receipts and photos, and submit a supplemental claim with the specific differences.'},{q:'What is a supplemental claim?',a:'A supplemental claim requests additional payment for costs that the original settlement did not cover. You submit it with new estimates, receipts, or documentation of items the adjuster missed.'}] },
  { id:'claim-dispute', name:'Dispute an Insurance Claim', description:'Build a structured dispute when the insurer position conflicts with documented facts or evidence, with a fact-based response and evidence matrix.', family:'Disputes & Appeals', risk:'HIGH', requiresReview:true, primaryKeyword:'dispute insurance claim', monthlySearches:210, cpc:35.86, competition:'LOW', supportingKeywords:['dispute insurance','disputing insurance claims','insurance claim dispute'], intake:['claim number','dispute reason','insurer position','your position','supporting facts','deadline'], requiredEvidence:['claim file','policy excerpts','photos','inspection reports','estimates','invoices','policy/claim correspondence'], outputs:['dispute summary','fact comparison table','evidence matrix','response letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'How do I dispute an insurance claim decision?',a:'Identify the specific point of disagreement, gather evidence contradicting the insurer\'s position, cite the relevant policy language, and file a written dispute within the deadline. Keep all communications documented.'},{q:'What is the difference between a dispute and an appeal?',a:'A dispute challenges the insurer\'s valuation or factual determination. An appeal challenges a formal denial. Both require written submissions but follow different processes and timelines.'},{q:'Can I request the insurer\'s claim file?',a:'In many states, you have the right to request the insurer\'s complete claim file, including adjuster notes, estimates, and correspondence. This can reveal errors or unsupported assumptions in their determination.'}] },
  { id:'coverage-denial', name:'Respond to a Coverage Denial', description:'Analyze a coverage denial and prepare a documented response citing policy language, covered perils, and supporting evidence.', family:'Disputes & Appeals', risk:'HIGH', requiresReview:true, primaryKeyword:'coverage denial', monthlySearches:170, cpc:0.00, competition:'LOW', supportingKeywords:['denial of coverage','coverage denial','denied coverage','insurance coverage denial'], intake:['denial letter','policy section cited','claimed peril','insurer reasoning','deadline'], requiredEvidence:['denial letter','policy/declarations page','photos','incident documentation','prior correspondence'], outputs:['coverage analysis','policy citation','evidence matrix','response letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is a coverage denial?',a:'The insurer says the loss is not covered by your policy — either the peril is excluded, the property is not insured, or a coverage condition was not met. The denial should cite the specific policy provision.'},{q:'How do I challenge a coverage denial?',a:'Read the cited policy exclusion, check if the peril is actually covered under a different section, gather evidence showing the loss meets coverage requirements, and file a written appeal citing the correct policy language.'},{q:'What is the difference between a coverage denial and a claim denial?',a:'A coverage denial says the policy does not cover the type of loss at all. A claim denial says the loss is covered but the claim itself is denied for other reasons (insufficient evidence, late filing, etc.).'}] },
  { id:'insurance-appeal', name:'Appeal an Insurance Denial', description:'Build a formal appeal around the denial reason, policy language, evidence, and requested outcome with a structured argument.', family:'Disputes & Appeals', risk:'HIGH', requiresReview:true, primaryKeyword:'appealing insurance denial', monthlySearches:260, cpc:35.86, competition:'LOW', supportingKeywords:['appeal insurance denial','appealing a claim','appealing an insurance claim','how to appeal insurance denial'], intake:['denial letter','appeal deadline','claim number','denial reason','policy provision cited','requested outcome'], requiredEvidence:['denial letter','policy documents','claim records','supporting evidence','prior correspondence'], outputs:['appeal argument','evidence index','response/appeal draft','mail-ready packet'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'How do I appeal an insurance denial?',a:'Read the denial letter, identify the reason and cited policy provision, gather contradicting evidence, and file a formal written appeal within the deadline. Address each reason the insurer gave and cite specific policy language supporting coverage.'},{q:'How long do I have to appeal?',a:'Deadlines vary by policy type, insurer, and state. Health insurance appeals often have shorter deadlines (30-180 days). Property/casualty appeals may allow longer. Check your policy and denial letter for the specific deadline.'},{q:'What if my appeal is denied?',a:'You can request external review (for health insurance), file a complaint with your state insurance commissioner, or pursue legal action. Keep records of all appeal submissions and insurer responses.'}] },
  { id:'supplemental-claim', name:'Supplemental Insurance Claim', description:'Request additional payment for costs the original settlement did not cover with new estimates, receipts, and a documented comparison.', family:'Disputes & Appeals', risk:'MEDIUM', requiresReview:true, primaryKeyword:'supplemental insurance claim', monthlySearches:140, cpc:11.50, competition:'LOW', supportingKeywords:['insurance supplement claim','supplemental claim insurance','supplemental claim','file a supplemental insurance claim'], intake:['original claim number','original settlement','additional costs','new estimates','items missed','receipts'], requiredEvidence:['original estimate/settlement','new contractor estimate','receipts for additional work','photos of additional damage','prior correspondence'], outputs:['supplemental summary','cost comparison','document checklist','supplemental request letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is a supplemental insurance claim?',a:'A supplemental claim requests additional payment beyond the original settlement for costs that were not included — additional damage discovered during repairs, underestimated line items, or new estimates.'},{q:'When can I file a supplemental claim?',a:'You can file when you discover the original settlement did not cover the full cost of repairs, additional damage is found during repair work, or the original estimate missed items. There is typically a time limit — check your policy.'},{q:'What documentation do I need for a supplement?',a:'You need the original estimate and settlement, the new estimate showing the difference, receipts for additional work, photos of additional or missed damage, and a clear comparison table showing what was paid vs. what is owed.'}] },
  { id:'business-interruption-claim', name:'Business Interruption Insurance Claim', description:'Organize a business interruption claim with financial records, closure documentation, and a documented period of restoration.', family:'Specialized Claims', risk:'CRITICAL', requiresReview:true, primaryKeyword:'business interruption insurance claim', monthlySearches:210, cpc:16.80, competition:'MEDIUM', supportingKeywords:['business interruption claim','business interruption insurance','business interruption coverage','lost income insurance claim'], intake:['business','policy','interruption cause','closure dates','revenue impact','extra expenses'], requiredEvidence:['business policy','financial statements/tax returns','profit and loss records','closure documentation','expense receipts','prior year comparison'], outputs:['interruption summary','financial impact analysis','period of restoration','document checklist','claim submission draft'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is business interruption insurance?',a:'Business interruption insurance covers lost income and extra expenses when a covered event forces your business to close temporarily. It typically requires physical damage to the property from a covered peril.'},{q:'How is business interruption calculated?',a:'It is based on your actual loss of income during the "period of restoration" — the time needed to repair or replace the damaged property. Insurers use financial records, prior year revenue, and projected income.'},{q:'What records do I need for a business interruption claim?',a:'You need financial statements, tax returns, profit and loss reports, payroll records, the business policy, documentation of the physical damage, closure dates, and receipts for extra expenses (temporary location, equipment rental, etc.).'}] },
  { id:'total-loss-claim', name:'Total Loss Insurance Claim', description:'Organize a total loss claim with valuation evidence, comparable sales, policy declarations, and a documented actual cash value or replacement cost argument.', family:'Specialized Claims', risk:'CRITICAL', requiresReview:true, primaryKeyword:'total loss insurance claim', monthlySearches:210, cpc:19.50, competition:'LOW', supportingKeywords:['total loss claim','insurance total loss','total loss vehicle insurance','total loss car insurance claim','total loss home insurance'], intake:['insurer','policy number','property type','damage extent','insurer valuation','your valuation','ACV vs RCV'], requiredEvidence:['policy/declarations page','damage photos','comparable sales/listings','appraisal report','repair estimate showing total loss','prior condition photos'], outputs:['valuation analysis','comparable evidence','document checklist','response/appeal letter'], guardrails:SHARED_GUARDRAILS, faqs:[{q:'What is a total loss in insurance?',a:'A total loss occurs when the cost to repair exceeds the property\'s value (or a threshold set by the insurer/state). For vehicles, this is typically when repair costs exceed 60-80% of the vehicle\'s value.'},{q:'How does the insurer value a total loss?',a:'For vehicles, insurers use actual cash value (ACV) based on comparable sales, market guides, and condition. For homes, they use replacement cost or ACV depending on your policy. You have the right to challenge the valuation.'},{q:'Can I dispute a total loss valuation?',a:'Yes. Gather comparable sales, get an independent appraisal, document the property\'s condition and upgrades, and present the evidence to the insurer. If they refuse, you may invoke the appraisal clause in your policy or file a complaint.'}] },
]

